UPDATE actions SET metadata = jsonb_set(
  jsonb_set(COALESCE(metadata, '{}'::jsonb), '{available_area_type}', '"total"'),
  '{guidance_link}',
  '"https://www.gov.uk/find-funding-for-land-or-farms/clig3-manage-grassland-with-very-low-nutrient-inputs"'
) WHERE code = 'CLIG3';

